!> Calculates the dot product of two single-precision complex floating-point vectors.
!
! ## Notes
!
! * Modified version of reference BLAS level1 routine (version 3.7.0). Updated to "free form" Fortran 95.
!
! ## Authors
!
! * Univ. of Tennessee
! * Univ. of California Berkeley
! * Univ. of Colorado Denver
! * NAG Ltd.
!
! ## History
!
! * Jack Dongarra, linpack, 3/11/78.
!
!   - modified 12/3/93, array(1) declarations changed to array(*)
!
! ## License
!
! From <http://netlib.org/blas/faq.html>:
!
! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
! >
! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
! >
! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
! >
! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {integer} N - number of indexed elements
! @param {Array<complex>} cx - first input array
! @param {integer} incx - `cx` stride length
! @param {Array<complex>} cy - second input array
! @param {integer} incy - `cy` stride length
! @returns {complex} dot product
!<
complex function cdotu( N, cx, incx, cy, incy )
  implicit none
  ! ..
  ! Scalar arguments:
  integer :: incx, incy, N
  ! ..
  ! Array arguments:
  complex :: cx(*), cy(*)
  ! ..
  ! Local scalars:
  complex :: ctemp
  integer :: i, ix, iy
  ! ..
  ctemp = (0.0,0.0)
  cdotu = (0.0,0.0)
  if ( N <= 0 ) then
    return
  end if
  ! ..
  if ( incx == 1 .AND. incy == 1 ) then
    ! ..
    ! Code for both increments equal to 1...
    do i = 1, N
      ctemp = ctemp + cx( i ) * cy( i )
    end do
  else
    ! ..
    ! Code for unequal increments or equal increments not equal to 1...
    ix = 1
    iy = 1
    if ( incx < 0 ) then
      ix = ( -N + 1 ) * incx + 1
    end if
    if ( incy < 0 ) then
      iy = ( -N + 1 ) * incy + 1
    end if
    do i = 1, N
      ctemp = ctemp + cx( ix ) * cy( iy )
      ix = ix + incx
      iy = iy + incy
    end do
  end if
  cdotu = ctemp
  return
end function cdotu